 void OnDesignStyleChanged(object sender,EventArgs e){if(!loading){RefreshPreview();UpdateButtons();}}
 Button ColorButton(string name,Color initial,Action<Color> set){var b=Btn(name,false);PaintColor(b,initial);b.Click+=delegate{using(var d=new ColorDialog{FullOpen=true,Color=b.BackColor})if(d.ShowDialog(this)==DialogResult.OK){set(d.Color);PaintColor(b,d.Color);RefreshPreview();}};return b;}
 void PaintColor(Button b,Color c){b.BackColor=c;b.ForeColor=c.GetBrightness()>.55?Color.Black:Color.White;b.Text="#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2");}
 Design AddStyleOptions(Design d){d.SourceIsAsset=photo==null;d.Caption=caption.Text;d.FontFamily=family.Text;d.TextColor=textColor;d.TextEffect=textEffect.Text;d.TextPosition=textPosition.Text;d.TextSize=(float)textSize.Value;d.Bold=textBold.Checked;d.Italic=textItalic.Checked;d.ReplaceGlyph=Selected!=null&&Selected.Kind=="glyph"&&replaceGlyph.Checked;d.Glyph=d.ReplaceGlyph?Char.ConvertFromUtf32(Int32.Parse(Selected.FrameName.Substring(5))):"";d.FrameStyle=frameStyle.Text;d.FrameColor=frameColor;d.FrameWidth=frameWidth.Value;d.Glow=frameGlow.Value;return d;}
 void UpdateStyleSelection(){loading=true;replaceGlyph.Enabled=Selected!=null&&Selected.Kind=="glyph";replaceGlyph.Checked=replaceGlyph.Enabled;loading=false;}
 void UpdateFontButtons(){if(applyFont==null)return;bool glyph=Game!=null&&Selected!=null&&Selected.Kind=="glyph";applyFont.Enabled=glyph&&Game.HasLoader;restoreFont.Enabled=glyph&&Catalog.Items.Any(a=>a.Group==Selected.Group&&edited.Contains(a.Key));}
